begin;
create function pg_temp.assert(ok boolean,label text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;return 'PASS: '||label;end$$;
create function pg_temp.error(statement text,expected text,label text) returns text language plpgsql as $$begin begin execute statement;exception when others then if sqlstate<>expected then raise;end if;return 'PASS: '||label;end;raise exception 'FAIL: expected error %',label;end$$;
select pg_temp.assert((select not public and file_size_limit=2097152 and allowed_mime_types=array['image/png'] from storage.buckets where id='product-media'),'private bounded PNG bucket');
insert into storage.objects(bucket_id,name) values('product-media','fixture.png');
set local role anon;
select pg_temp.error($q$insert into storage.objects(bucket_id,name) values('product-media','anonymous.png')$q$,'42501','anonymous direct upload denied despite broad policy');
select pg_temp.assert((select count(*)=0 from storage.objects where bucket_id='product-media'),'anonymous private object denied');
with removed as (delete from storage.objects where bucket_id='product-media' returning id) select pg_temp.assert((select count(*)=0 from removed),'anonymous direct delete affects no assets');
reset role;set local role authenticated;
select pg_temp.error($q$insert into storage.objects(bucket_id,name) values('product-media','customer.png')$q$,'42501','authenticated direct upload denied');
with changed as (update storage.objects set name='evil.png' where bucket_id='product-media' returning id) select pg_temp.assert((select count(*)=0 from changed),'authenticated overwrite affects no assets');
with removed as (delete from storage.objects where bucket_id='product-media' returning id) select pg_temp.assert((select count(*)=0 from removed),'authenticated direct delete affects no assets');
with changed as (update storage.buckets set public=true where id='product-media' returning id) select pg_temp.assert((select count(*)=0 from changed),'browser cannot publish private bucket');
reset role;set local role service_role;
insert into storage.objects(bucket_id,name) values('product-media','server-fixture.png');
select pg_temp.assert((select count(*)=2 from storage.objects where bucket_id='product-media'),'trusted server storage path allowed');
reset role;
select pg_temp.assert((select count(*)=2 from storage.objects where bucket_id='product-media'),'referenced object preserved after browser mutation attempts');
rollback;
